    CodeGen cg = new CodeGen(this);
    cg.cw = new CodeGenClassWriter(ClassWriter.COMPUTE_FRAMES, cw);
    cg.cw.visitSource(NodeUtil.getSpan(x).begin.getFileName(), null);

